import os,stat,json,hashlib,re
from pathlib import Path
def error(e): return {"error":type(e).__name__,"errno":getattr(e,"errno",None)}
def candidate(p):
 r={"path":str(p)}
 try:
  s=p.lstat();r.update(uid=s.st_uid,gid=s.st_gid,mode=oct(stat.S_IMODE(s.st_mode)),size=s.st_size)
  r["symlink"]=os.readlink(p) if p.is_symlink() else None
  q=p.resolve(strict=True);r["resolved"]=str(q);t=q.stat()
  if not stat.S_ISREG(t.st_mode): return r
  h=hashlib.sha256()
  with q.open("rb") as f:
   head=f.read(16384);h.update(head)
   while True:
    c=f.read(1024*1024)
    if not c:break
    h.update(c)
  r["resolved_bytes"]=t.st_size;r["sha256"]=h.hexdigest()
  r["kind"]="ELF" if head[:4]==b"\x7fELF" else "script" if head.startswith(b"#!") else "other"
  if r["kind"]=="script":
   r["interpreter"]=head.splitlines()[0].decode("utf-8","replace")[:160]
   r["has_exec"]=bool(re.search(rb"\bexec\b",head))
   r["saved_session_literal"]=b"__session-run" in head
   text=head.decode("utf-8","replace")
   r["literal_ssmcp_paths"]=sorted(set(re.findall(r"/[A-Za-z0-9_./-]*ssmcp[A-Za-z0-9_./-]*",text)))[:12]
 except OSError as e:r.update(error(e))
 return r
